// Opens files one after another in the example app and checks that every
// replaced player is torn down: its threads exit and nothing crashes. Then
// checks that the plugin destroys players a hot restart left behind, and
// that their events do not reach the isolate that is gone.
//
//   cd flutter/example && flutter test integration_test -d macos
//
// Needs the media generated by tool/regression.sh in /tmp/lychee-media, or
// in the directory given with --dart-define=LYCHEE_MEDIA=... On Android,
// `flutter test` reinstalls the app, so serve the media instead
// (tool/serve_media.py) and pass LYCHEE_MEDIA=http://10.0.2.2:8765.

import 'dart:ffi';
import 'dart:io';
import 'dart:isolate';

import 'package:ffi/ffi.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:lychee_player/lychee_player.dart';
import 'package:lychee_player_example/main.dart';

const _mediaDir = String.fromEnvironment(
  'LYCHEE_MEDIA',
  defaultValue: '/tmp/lychee-media',
);
const _media = [
  '$_mediaDir/h264_aac.mp4',
  '$_mediaDir/hevc10.mp4',
  '$_mediaDir/vp9_opus.webm',
  '$_mediaDir/rotated.mp4',
];

/// Thread names in this process: from `sample` on macOS, from
/// GetThreadDescription on Windows, from /proc on Linux and Android.
Future<List<String>> _threadNames() async {
  if (Platform.isWindows) {
    return _windowsThreadNames();
  }
  if (!Platform.isMacOS) {
    final names = <String>[];
    for (final task in Directory('/proc/self/task').listSync()) {
      try {
        names.add(File('${task.path}/comm').readAsStringSync().trim());
      } on FileSystemException {
        // The thread exited after the listing.
      }
    }
    return names;
  }
  final file = '${Directory.systemTemp.path}/lychee-sample-$pid.txt';
  await Process.run('sample', ['$pid', '1', '-file', file]);
  final names = <String, String>{};
  final pattern = RegExp(r'Thread_(\d+): (\S+)');
  for (final line in await File(file).readAsLines()) {
    final match = pattern.firstMatch(line);
    if (match != null) {
      names[match[1]!] = match[2]!;
    }
  }
  return names.values.toList();
}

List<String> _windowsThreadNames() {
  final kernel32 = DynamicLibrary.open('kernel32.dll');
  final snapshot = kernel32.lookupFunction<IntPtr Function(Uint32, Uint32),
      int Function(int, int)>('CreateToolhelp32Snapshot');
  final first = kernel32.lookupFunction<Int32 Function(IntPtr, Pointer<Uint32>),
      int Function(int, Pointer<Uint32>)>('Thread32First');
  final next = kernel32.lookupFunction<Int32 Function(IntPtr, Pointer<Uint32>),
      int Function(int, Pointer<Uint32>)>('Thread32Next');
  final openThread = kernel32.lookupFunction<
      IntPtr Function(Uint32, Int32, Uint32),
      int Function(int, int, int)>('OpenThread');
  final description = kernel32.lookupFunction<
      Int32 Function(IntPtr, Pointer<Pointer<Utf16>>),
      int Function(int, Pointer<Pointer<Utf16>>)>('GetThreadDescription');
  final localFree =
      kernel32.lookupFunction<IntPtr Function(Pointer), int Function(Pointer)>(
          'LocalFree');
  final closeHandle = kernel32
      .lookupFunction<Int32 Function(IntPtr), int Function(int)>('CloseHandle');

  const snapThread = 0x4;
  const queryLimitedInformation = 0x0800;
  final names = <String>[];
  final threads = snapshot(snapThread, 0);
  // THREADENTRY32: dwSize, cntUsage, th32ThreadID, th32OwnerProcessID, ...
  final entry = calloc<Uint32>(7);
  final text = calloc<Pointer<Utf16>>();
  entry[0] = 28;
  for (var ok = first(threads, entry); ok != 0; ok = next(threads, entry)) {
    if (entry[3] != pid) continue;
    final thread = openThread(queryLimitedInformation, 0, entry[2]);
    if (thread == 0) continue;
    if (description(thread, text) >= 0) {
      names.add(text.value.toDartString());
      localFree(text.value);
    }
    closeHandle(thread);
  }
  calloc.free(entry);
  calloc.free(text);
  closeHandle(threads);
  return names;
}

Future<Map<String, int>> _countThreads() async {
  final names = await _threadNames();
  int count(bool Function(String) test) => names.where(test).length;
  // The plugin's vsync thread stands in for the display link on Android and
  // Windows; the core's own audio threads for CoreAudio's IO thread.
  bool isVsync(String n) => n.contains('CVDisplayLink') || n == 'lychee-vsync';
  const audioThreads = {
    'com.apple.audio.IOThread.client',
    'AudioTrack',
    'lychee-pulse',
    'lychee-wasapi',
  };
  return {
    'lychee': count(
      (n) =>
          n.startsWith('lychee-') && !isVsync(n) && !audioThreads.contains(n),
    ),
    'audio-io': count(audioThreads.contains),
    'display-link': count(isVsync),
  };
}

void main() {
  final binding = IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  // macOS reports a fully covered window as hidden, and Flutter then stops
  // scheduling frames, so pump() would wait forever while the test runs
  // behind other windows. Ignore lifecycle changes and keep frames on.
  SystemChannels.lifecycle.setMessageHandler((_) async => null);
  binding.handleAppLifecycleStateChanged(AppLifecycleState.resumed);

  testWidgets('switching files releases the previous player', (tester) async {
    await tester.pumpWidget(const ExampleApp());

    Future<void> wait(Duration duration) async {
      await Future<void>.delayed(duration);
      await tester.pump();
    }

    Future<void> open(String path) async {
      await tester.enterText(find.byType(TextField), path);
      await tester.tap(find.text('Open'));
      await tester.pump();
    }

    await open(_media[0]);
    await wait(const Duration(milliseconds: 1500));
    final before = await _countThreads();
    final rssBefore = ProcessInfo.currentRss;

    for (var i = 0; i < 10; i++) {
      await open(_media[i % _media.length]);
      await wait(const Duration(milliseconds: 1500));
      // The status line ends with the state name, "error: <message>".
      expect(find.textContaining('   error'), findsNothing);
    }

    // Two opens in a row, so the second starts before the first has created
    // its player. Calls onPressed directly: a second synthetic tap that
    // quickly is not delivered.
    await tester.enterText(find.byType(TextField), _media[0]);
    final button = tester.widget<FilledButton>(find.byType(FilledButton));
    button.onPressed!();
    button.onPressed!();
    await tester.pump();
    await wait(const Duration(seconds: 3));

    final threads = await _countThreads();
    final rssGrowth = (ProcessInfo.currentRss - rssBefore) >> 20;
    // ignore: avoid_print
    print('threads before: $before, after: $threads, rss +$rssGrowth MB');
    // One player playing audio and video: lychee-player (control),
    // lychee-demux (read), lychee-adecode and lychee-vdecode.
    expect(threads['lychee'], 4);
    expect(threads['audio-io'], lessThanOrEqualTo(1));
    // CoreVideo pools display link threads; a leaked link would add one per
    // switch.
    expect(
      threads['display-link']!,
      lessThanOrEqualTo(before['display-link']! + 2),
    );
  });

  testWidgets('disposeAll destroys players a hot restart left', (tester) async {
    // Lets the example dispose of its player.
    await tester.pumpWidget(const SizedBox());
    await Future<void>.delayed(const Duration(seconds: 1));
    expect((await _countThreads())['lychee'], 0);

    // What a previous isolate leaves: a playing player behind a texture,
    // its events bound to an isolate that is gone. A child isolate makes it
    // the way the app does and ends without dispose(), as a hot restart
    // ends the root isolate.
    final token = RootIsolateToken.instance!;
    final url = _media[0];
    await Isolate.run(() async {
      BackgroundIsolateBinaryMessenger.ensureInitialized(token);
      final player = await LycheePlayer.create();
      player.open(url);
      player.play();
    });
    // Over http on an emulator, opening takes a few seconds.
    var playing = 0;
    for (var i = 0; i < 20 && playing < 4; i++) {
      await Future<void>.delayed(const Duration(milliseconds: 500));
      playing = (await _countThreads())['lychee']!;
    }
    expect(playing, 4);
    // Plays to its end (12 s), sending events all the way. The isolate
    // cleared the callback before deleting it; otherwise the VM aborts
    // ("Callback invoked after it has been deleted") or hands them to
    // whatever callback reuses its slot.
    await Future<void>.delayed(const Duration(seconds: 14));
    expect((await _countThreads())['lychee'], greaterThan(0));

    const channel = MethodChannel('lychee_player');
    await channel.invokeMethod<void>('disposeAll');
    expect((await _countThreads())['lychee'], 0);
  });
}
